-- Schema ER_DIAGRAM.drawio: UUID generated by JPA; no cascading deletes.

CREATE TABLE categoria (
    id uuid PRIMARY KEY,
    nome varchar(100) NOT NULL UNIQUE CHECK (btrim(nome) <> ''),
    descrizione text
);

CREATE TABLE tipo_articolo (
    id uuid PRIMARY KEY,
    id_categoria uuid NOT NULL REFERENCES categoria(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    codice_articolo varchar(64) NOT NULL UNIQUE CHECK (btrim(codice_articolo) <> ''),
    descrizione text NOT NULL CHECK (btrim(descrizione) <> ''),
    marca varchar(100) NOT NULL CHECK (btrim(marca) <> ''),
    modello varchar(100) NOT NULL CHECK (btrim(modello) <> ''),
    costo numeric(12,2) CHECK (costo >= 0)
);

CREATE INDEX ix_tipo_articolo_id_categoria ON tipo_articolo(id_categoria);

CREATE TABLE file_asset (
    id uuid PRIMARY KEY,
    storage_backend varchar(16) NOT NULL CHECK (btrim(storage_backend) <> '' AND storage_backend IN ('LOCAL', 'S3')),
    storage_namespace varchar(128) NOT NULL CHECK (btrim(storage_namespace) <> ''),
    storage_key text NOT NULL CHECK (btrim(storage_key) <> ''),
    original_name varchar(255) NOT NULL CHECK (btrim(original_name) <> ''),
    mime_type varchar(127) NOT NULL CHECK (btrim(mime_type) <> ''),
    byte_size bigint NOT NULL CHECK (byte_size >= 0),
    sha256 char(64) NOT NULL CHECK (btrim(sha256) <> '' AND sha256 ~ '^[0-9a-fA-F]{64}$'),
    visibility varchar(16) NOT NULL CHECK (btrim(visibility) <> '' AND visibility IN ('PUBLIC', 'PRIVATE')),
    created_at timestamptz NOT NULL,
    CONSTRAINT uq_file_asset UNIQUE (storage_backend, storage_namespace, storage_key)
);

CREATE TABLE immagine_articolo (
    id uuid PRIMARY KEY,
    file_asset_id uuid NOT NULL REFERENCES file_asset(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    alt_text varchar(255) NOT NULL CHECK (btrim(alt_text) <> ''),
    sort_order integer NOT NULL CHECK (sort_order >= 0),
    id_tipo_articolo uuid NOT NULL REFERENCES tipo_articolo(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT uq_immagine_articolo UNIQUE (id_tipo_articolo, file_asset_id)
);

CREATE INDEX ix_immagine_articolo_file_asset_id ON immagine_articolo(file_asset_id);

CREATE TABLE documento_articolo (
    id uuid PRIMARY KEY,
    file_asset_id uuid NOT NULL REFERENCES file_asset(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    version varchar(50) NOT NULL CHECK (btrim(version) <> ''),
    id_tipo_articolo uuid NOT NULL REFERENCES tipo_articolo(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT uq_documento_articolo UNIQUE (id_tipo_articolo, file_asset_id, version)
);

CREATE INDEX ix_documento_articolo_file_asset_id ON documento_articolo(file_asset_id);

CREATE TABLE tipo_intervento (
    id uuid PRIMARY KEY,
    nome varchar(150) NOT NULL CHECK (btrim(nome) <> '')
);

CREATE TABLE tipo_impianto (
    id uuid PRIMARY KEY,
    nome varchar(150) NOT NULL CHECK (btrim(nome) <> '')
);

CREATE TABLE tipo_assistenza (
    id uuid PRIMARY KEY,
    nome varchar(150) NOT NULL CHECK (btrim(nome) <> '')
);

CREATE TABLE fornitore (
    id uuid PRIMARY KEY,
    ragione_sociale varchar(255) NOT NULL CHECK (btrim(ragione_sociale) <> ''),
    indirizzo varchar(255) NOT NULL CHECK (btrim(indirizzo) <> ''),
    partita_iva varchar(20),
    codice_fiscale varchar(16),
    telefono varchar(32),
    email varchar(254),
    iban varchar(34)
);


